from lib import *
S = SS('k22')
F1 = [['a.yaml', 'c-shared → :9821, u-a = token-from-A'], ['b.yaml', 'c-shared → :9822, u-a = token-from-B-for-u-a'], ['合并后', 'c-shared → :9821,u-a = token-from-A'], ['current-context', 'ctx-a(a 先设了)']]
F2 = [['b.yaml', '排在前面'], ['a.yaml', '排在后面'], ['合并后', 'c-shared → :9822,u-a = token-from-B-for-u-a'], ['current-context', 'ctx-b']]
F3 = [['--context', '整套换'], ['--cluster', '只换服务器'], ['--user', '只换令牌'], ['--namespace', '只换命名空间'], ['--kubeconfig', '环境变量整个忽略']]
F4 = [['kubeconfig 文件', 'sub/ca.pem(相对路径)'], ['解析基准', 'kubeconfig 所在目录'], ['--flatten', '把文件内容嵌进去'], ['config view', '默认把 token 遮成 REDACTED']]
PANELS = [('f', 'flow', 'kubeconfig 的解析'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("两个手写的 kubeconfig:a.yaml 与 b.yaml 里都有集群 c-shared、用户 u-a、context ctx-shared,内容不同。KUBECONFIG=a.yaml:b.yaml:current-context=ctx-a(a 先设了);c-shared 的服务器是 a 的(:9821),u-a 的令牌是 token-from-A;只在 b 里有的 c-b、u-b、ctx-b 被并进来。同名条目先出现的文件胜出,不同名的合并。", f=fl(F1, cur=[2], done=[0, 3], mark=[1]), t=tl(S(1), mark=lidx(S(1), "'c-shared': 'https://127.0.0.1:9821'", "'u-a': 'token-from-A'"), done=lidx(S(1), 'current-context=ctx-a')), kv=KV([['同名条目', '先出现的文件生效,后面的被忽略'], ['不同名', '合并'], ['current-context', '第一个设了它的文件']], ['同名条目'])),
    step("把顺序反过来 KUBECONFIG=b.yaml:a.yaml:current-context=ctx-b;c-shared 的服务器变成 b 的(:9822),u-a 的令牌变成 token-from-B-for-u-a,ctx-shared 用 u-b;--minify 只留当前 context 用到的部分:server=https://127.0.0.1:9822、namespace=ns-b。同样两个文件,顺序不同,实际连到哪个集群、用哪个令牌就不同。", f=fl(F2, cur=[2], done=[0, 3], mark=[1]), t=tl(S(2), mark=lidx(S(2), "'c-shared': 'https://127.0.0.1:9822'", "token-from-B-for-u-a"), done=lidx(S(2), 'current-context=ctx-b', '--minify')), kv=KV([['顺序有意义', '同名冲突时靠它决定'], ['--minify', '只显示当前 context 实际用到的'], ['排查连错集群', '先看 KUBECONFIG 的顺序']], ['顺序有意义'])),
    step("真的发一次 kubectl get pods,看假 apiserver 收到什么:默认请求端口 9821、/api/v1/namespaces/ns-a/pods、Bearer token-from-A;--context=ctx-b 整套换成 9822、ns-b、token-from-B;--cluster=c-b 只换服务器(仍是 ns-a、token-from-A);--user=u-b 只换令牌;--namespace=other 只换路径;--token=cli-token 覆盖令牌;--kubeconfig=b.yaml 时环境变量里的 a.yaml:b.yaml 被整个忽略(不是合并);不存在的 context 报 Error in configuration: context was not found。", f=fl(F3, cur=[1, 2, 3], mark=[0, 4]), t=tl(S(3), mark=lidx(S(3), '--cluster=c-b(只换集群)', '--user=u-b(只换用户)', '--namespace=other(只换'), done=lidx(S(3), '--context=ctx-b', '--kubeconfig=b.yaml')), kv=KV([['--context', '整套替换'], ['--cluster / --user / --namespace', '各换各的那一项'], ['--kubeconfig', '完全忽略 KUBECONFIG 环境变量'], ['--token', '直接覆盖令牌']], ['--kubeconfig'])),
    step("路径与遮掩:kubectl config view 默认把令牌显示成 token: REDACTED;CA 写成相对路径 sub/ca.pem,工作目录是 / 时仍被正确解析(以 a.yaml 所在目录为基准),--flatten 会把文件内容嵌成 certificate-authority-data;把 sub/ca.pem 删掉后 kubectl get nodes 报 unable to read certificate-authority <…>/k22/sub/ca.pem for c-shared。kind 为 kx-main 生成的 kubeconfig 只有一个 context:kind-kx-main。", f=fl(F4, cur=[1], mark=[3], done=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'REDACTED', 'unable to read certificate-authority'), done=lidx(S(4), '--flatten')), kv=KV([['相对路径', '相对于 kubeconfig 文件所在目录'], ['--flatten', '搬家时把外部文件嵌进去'], ['config view', '默认遮掉敏感字段,--raw 才显示']], ['相对路径'])),
]
A = mkartk('k22', 22, 'Kubernetes,kubeconfig,KUBECONFIG,contexts,clusters,users,真实验证,动画演示',
    '用两个手写的 kubeconfig 和两个本地假 apiserver(只记录请求)实测 kubectl 如何解析 kubeconfig:KUBECONFIG=a:b 时同名的 cluster/user/context 先出现的文件胜出、不同名的合并、current-context 取第一个设了它的文件,顺序反过来结果就不同;--context 整套替换,--cluster/--user/--namespace/--token 各换一项,--kubeconfig 完全忽略环境变量;相对路径以 kubeconfig 所在目录为基准,config view 默认遮掉令牌。',
    '连错集群、用错账号、命名空间莫名其妙——多半是 kubeconfig 的合并和覆盖规则没搞清。这篇不看文档,用两份内容故意冲突的文件和两个假 apiserver,把环境变量顺序、命令行参数覆盖、相对路径解析都跑成可以直接对照的结果。',
    [('ctx-a / ctx-b', '同样两个文件,KUBECONFIG 顺序 a:b 与 b:a 时的 current-context'), ('9821 / 9822', '同一条 kubectl get pods,默认与 --context=ctx-b 时请求实际打到的两个假 apiserver 端口'), ('REDACTED', 'kubectl config view 默认对令牌的显示')],
    [('同名条目:先到先得', '<p>a.yaml 和 b.yaml 里都有 <code>c-shared</code> 集群、<code>u-a</code> 用户、<code>ctx-shared</code> context,内容不同。<code>KUBECONFIG=a.yaml:b.yaml</code> 合并后:<code>current-context=ctx-a</code>(第一个设了它的文件),<code>c-shared</code> 指向 a 的服务器,<code>u-a</code> 的令牌是 <code>token-from-A</code>;只在 b 里有的 <code>c-b</code>、<code>u-b</code>、<code>ctx-b</code> 被并进来。规则:同名条目先出现的文件胜出,后面的整条被忽略;不同名的合并。</p>'),
     ('顺序反过来', '<p><code>KUBECONFIG=b.yaml:a.yaml</code> 之后:<code>current-context=ctx-b</code>,<code>c-shared</code> 变成 b 的服务器,<code>u-a</code> 的令牌变成 <code>token-from-B-for-u-a</code>,<code>ctx-shared</code> 引用的用户也变成 <code>u-b</code>。同样的两个文件,顺序不同,实际连到哪、用谁的令牌就不同——排查“怎么连到别的集群了”,先看 <code>KUBECONFIG</code> 里的顺序,再用 <code>kubectl config view --minify</code> 看实际生效的那一份。</p>'),
     ('命令行覆盖', '<p>真的发一次 <code>kubectl get pods</code>,看假 apiserver 收到什么:默认是 9821、<code>/api/v1/namespaces/ns-a/pods</code>、<code>Bearer token-from-A</code>。<code>--context=ctx-b</code> 整套换;<code>--cluster</code> 只换服务器(命名空间和令牌不变),<code>--user</code> 只换令牌,<code>--namespace</code> 只换路径里的命名空间,<code>--token</code> 直接覆盖令牌。<code>--kubeconfig</code> 不是“再合并一个文件”,而是让环境变量里的 KUBECONFIG 被整个忽略。注意:<code>kubectl config view --minify --cluster=…</code> 这类命令只是打印文件内容,不会应用这些覆盖,验证覆盖要看真实请求。</p>'),
     ('路径与遮掩', '<p>kubeconfig 里的相对路径(这里是 <code>certificate-authority: sub/ca.pem</code>)以 kubeconfig 文件所在的目录为基准,不是当前工作目录;<code>--flatten</code> 把引用的文件内容嵌成 <code>certificate-authority-data</code>,搬到别的机器上不会失效。文件缺了,报 <code>unable to read certificate-authority … for c-shared</code>,错误里带着解析后的绝对路径。<code>kubectl config view</code> 默认把令牌显示成 <code>REDACTED</code>,要看原文得加 <code>--raw</code>。</p>')],
    steps,
    [ENV_K + '。两份手写的 kubeconfig(a.yaml、b.yaml,放在实验目录,令牌是假字符串);“集群”是宿主机上两个用 Python http.server 起的 HTTPS 假 apiserver(端口 9821 与 9822,自签证书,只记录收到的路径与 Authorization 头,对 /api、/api/v1、/apis 回最小的发现响应),所以第 3 节看到的是 kubectl 真实发出的请求;合并结果取自 kubectl config view -o json;每条命令都显式设置 KUBECONFIG 或 --kubeconfig,并把 KUBECACHEDIR 指到实验目录,没有读写 ~/.kube;实验后删除了临时文件;每种情形各一次',
     '没有验证:client-go 的 exec 凭据插件(users.user.exec)与 auth-provider;in-cluster 配置(Pod 里没有 kubeconfig 时的回退);KUBECONFIG 里文件不存在或格式错误时的行为;kubectl config set / use-context 对多文件的写入位置(写入第一个文件);proxy-url、tls-server-name 等其他集群字段;默认 ~/.kube/config 的回退(为了不碰用户自己的文件没有测)'],
    'kubeconfig 解析', PANELS)
